"""Documentation from independent manifests plus explicit gate evidence only."""
import json


def table(headers,rows):
    return "| "+" | ".join(headers)+" |\n| "+" | ".join("---" for _ in headers)+" |\n"+"\n".join("| "+" | ".join(str(item).replace("|","\\|") for item in row)+" |" for row in rows)+"\n"


def documents(coverage,manifest,sidecars,inputs,mutations,hands,pending,evidence):
    closed=evidence["all_gates"]=="passed"
    outcome="Outcome A — D9 Recovery Oracle Subset Closed" if closed else "Verification pending — no Outcome A claim"
    common="\nStarting HEAD: `c5b49850d9ba0dce75255f152498468fe8e93762`. This phase targets only 16 original D9-Recovery cases; the 22 Control baseline is retained. Closure depends on the recorded committed gates. D10 independent values are Pending for all 78; B01/B02 Closure and B03–B07 remain BLOCKING. No later phase or runtime/publication capability is created.\n"
    case_rows=[];origins={name:0 for name in ["IndependentAlgebra","ExactDeclarations","ContentIdentity","DiagnosticOnly"]}
    for row in manifest["cases"]:
        s=sidecars[row["case_id"].split("/")[-1]];facts=s["facts"];actions=facts["d9_root_recovery"]["actions"]["actions"]
        case_rows.append([row["case_id"],row["expected_stage"],row["recovery_sources"],[action["local_bound"]["upper"]["upper"] if action["local_bound"] else None for action in actions],[action["root_bound"]["upper"]["upper"] for action in actions],row["instance_coverage"]["required"],row["instance_coverage"]["diagnostic"]])
        for name in origins:origins[name]+=s["oracle_provenance"][name]
    case_table=table(["CaseId","Stage","Sources","Local uppers","Root uppers","Required visits","Diagnostic visits"],case_rows)
    counts=table(["Count domain","Value"],list(coverage["type_level"].items())+list(coverage["projection_type_level"].items()))
    source_delta=sorted({f["typed_field_path"] for f in coverage["fields"] if f["required_comparison"] and f["case_applicability"]}-set(coverage["baseline_applicable_source_paths"]))
    projection_delta=sorted({f["field_path"] for f in coverage["projection_fields"] if f["classification"]!="DiagnosticOnly" and f["case_applicability"]}-set(coverage["baseline_applicable_projection_paths"]))
    docs={}
    texts={
        "overview":outcome+".\n\nThe declaration-driven RecoveryModel subclasses the independent 4A Control model; it recalculates every affected Node, E/Phi/R/F/U/X/K fact, scope, alias, proof and closure. Expected never reads Rust reports or target outputs. The test-only getter is unchanged; runners are under tests/support, without weakening the original static scan.\n\n"+case_table,
        "recovery-source-identity":"Identity is `(caller SemanticIrDigest, source ComputationId, exact ComponentContractDigest, forward entry ordinal, complete RecoveryActionIdentity)`. Action identity includes full Forward atom, action kind and full action atom, including every qualifier/selector. Equal pins or atoms at distinct call sites remain separate. Ordinals are declaration-derived positions in canonical effect rows, not action-array indexes. Input identity binds exact bytes/checksum; resolver associations are recaptured from the exact declared caller.\n\n"+table(["CaseId","Input SHA256","Root node","Source nodes"],[(r["case_id"],r["input_sha256"],r["root_computation"],r["recovery_sources"]) for r in manifest["cases"]]),
        "local-root-bounds":"AF-SEMANTIC-0150/0155: factor-free seed × activation upper × attempts upper, followed by each unique applicable logical factor once. The nearest CompensationScope defines the one-activation Local coordinate; Root includes all enclosing factors. Root owner has explicit local_bound=None. Shared same-atom ceilings infer seed=floor(C/(1+sum multipliers)), never seed=C. Exact numeric ceilings do not discharge action eligibility.\n\n"+case_table,
        "multiplicity-algebra":"Factor identity is `(caller digest, control node, Retry/Iterate kind)`. RETRY logical repetitions and physical attempts stay separate; only logical upper multiplies potential. ITERATE applies total logical count, never max_inflight. Unique factors are checked against ordered control paths; duplicated identities fail before arithmetic. Descriptive occurrence families are independently propagated and are not a second multiplication. U64 overflow rejects; it never wraps, saturates or truncates.\n\n"+json.dumps(coverage["subsets"],indent=2),
        "compensation-ownership":"Owned declaration edges determine nearest CompensationScope. Entering an inner scope resets local factors; Root factors remain. Outer scope does not re-register inner local actions. SourceAction walks preserve original ownership and ordered path. No scope ancestor means RootRecovery, not an invented scope. Retry(CompScope) and CompScope(Retry) differ in Local potential. Source/action/profile duplication is preserved; no actual recovery or committed-event order is inferred.",
        "guard-evidence":"AF-CONTRACT-0017 and AF-SEMANTIC-0156: forward guard contained by action guard, not the reverse. Guard containment is Unconditional or exact InputEquals with typed constants; no solver is introduced. Failed containment alone is Unproven without a valid typed domain countermodel. The original 16 guards are Unconditional, so countermodel=None is exact and compared, not omitted. Entry ordinals are explicit Option<usize>; nullable presence is registered while the finite path count remains 937. Positive eligibility stays RequiresEvidence. F04 global SELECT/RACE/HANDLE suppression remains open and is not path-locally repaired. Typed Bool and invalid-type hand witnesses have explicit premises; this does not promote uninstantiated D10 witnesses.",
        "k-epsilon-oracle":"Action effect potential is a separate proof input, not a second executed event or new epsilon charge. Epsilon requirement folds with ordered sum, exclusive max, conditional handlers, loser-retaining race and single repetition factors. Full atoms/qualifiers/selectors/guards remain. Exact same-atom Forward opportunity is added once to K opportunity (1+6=7 hand premise); the declared aggregate envelope is not incremented. Source occurrences and conditional action identities stay separate. D9 compares against already-derived Root epsilon; D10 export-row witnesses remain Pending. F01 same-row/one-use capacity regressions are retained, never splicing bounds and guards from different rows.",
        "recovery-usage-oracle":"Exact profile identities, phase/meter/unit/aggregation and activation/attempt uppers come from declarations and exhaustive catalog content. The original 16 explicitly declare an exhaustive EMPTY meter set; that is not a missing required meter or a zero for arbitrary coordinates. Added valid profiles cover nonempty finite and explicit-zero usage; finite-meter negative premises cover missing/nonfinite/overflow/unsupported cases. K-required Usage multiplies per-attempt bounds by action potential and compares with existing U.recovery; it is never added to U or mixed with Forward. Active-source empty profiles are accepted only when the exact catalog says the complete set is empty.",
        "source-closure":"Five verdicts are independently accounted: source node multiset against owned leaf traversal; action binding multiset by exact source/action; complete profile multiset by source/binding; unique factor identities against control paths; total soundness from the complete prior accountings plus checked derivations. Equal contract/atom/profile contents at different call sites are not deduplicated. Missing source/profile/factor cannot become empty or zero. Root action objects retain source, seed, target, owner, both bound coordinates, both occurrences, binding, both Usage projections, Guard Option/coordinates, eligibility and path. All required payloads compare; only reviewed human explanation text is DiagnosticOnly.",
        "full-field-differential":"Both sides first validate the same closed 4A grammar, then compare every required value. This is not an action-count/upper-only test. Original cases are freshly run through D0–D9 (and existing D10 regression); diagnostic actual files are emitted only for comparison, never for generation.\n\n"+case_table+"\n"+table(["Independent origin","Visits"],origins.items())+"\n"+json.dumps(manifest["instance_totals"],indent=2),
        "comparator-mutations":"Preserved: 68 legacy integrity self-tests and 42 independent 4A mutations. New Recovery mutations start only from independently frozen Expected. Both-side root_bound omission and unexpected fields are rejected by shape, before equality. Arrays retain multiplicity; proof arrays canonicalize without deduplication. Deep paths are reported.\n\n"+table(["Mutation","Typed path"],[(r["mutation_id"],".".join(r["path"])) for r in mutations]),
        "hand-calculation":"The original 37 hand vectors remain unchanged. New literal premises distinguish local/root, nested ownership, distinct sources, logical/physical factors, same-atom seed, usage, missing evidence, unbounded/overflow and typed guards. Synthetic witnesses establish only their declared static premises, not Checked/runtime capabilities.\n\n"+"\n".join("## "+row["vector_id"]+"\n\n```json\n"+json.dumps(row,indent=2)+"\n```\n" for row in hands),
        "coverage-delta":"The type graph is unchanged: 264 record/sum types, six U32 terminals, 1079 slots (1074 required/five diagnostics). Projection is 937 paths (933 required/four diagnostics). 4A baseline remains 268 source /332 projection /120117 required visits. Cumulative applicability is a UNION, not 22-count+16-count addition.\n\n"+counts+"\n## Newly applicable source paths\n\n"+"\n".join("- `"+p+"`" for p in source_delta)+"\n\n## Newly applicable projection paths\n\n"+"\n".join("- `"+p+"`" for p in projection_delta)+"\n\n## Pending source paths\n\n"+"\n".join("- `"+p+"`" for p in pending["source_fields"])+"\n\n## Pending projection paths\n\n"+"\n".join("- `"+p+"`" for p in pending["projection_fields"]),
        "proof-boundaries":"D9 static possibility is not a receipt, applied-effect state, reconciliation success, dispatch authority, worker admission or refund. D10 assertion/full compiler content/context manifest/mappings/preflight/nine-dimension proof/execution child/missing evidence/violation witness/capability derivation remain Pending for all78. Other40 CaseIds remain Pending for new full-field Oracle. F01/F02 CLOSED; F03/F04 OPEN/P2; 84 Applied RuleIds are not a complete transitive closure.\n\n"+"\n".join("- `"+case+"`" for case in pending["other_case_ids"]),
        "readiness":outcome+".\n\n"+("D9 Control 22 + Recovery16 = specialized38 closed. 4C.1B.4C eligibility is established by this subset gate only; it is NOT started." if closed else "Fresh production and committed gates remain pending. No later-phase admission is claimed.")+" Full D9/D10 and B01/B02 closure remain incomplete/blocking.",
        "gate-report":"This gate log affects documentation only, never Expected semantics. Exact code-vs-document HEADs are distinguished; no costly test is claimed at a later doc-only HEAD. All current generators run twice with byte equality; original512, original4A Expected/37hands and all frozen wire/hash/production surfaces are preserved.\n\n```json\n"+json.dumps(evidence,indent=2)+"\n```\n\n"+table(["Real input vector","Expected stage"],[(row["vector_id"],row["expected_stage"]) for row in inputs]),
    }
    for name,text in texts.items():docs["phase-04c1b4b-"+name+".md"]="# Phase 4C.1B.4B — "+name.replace("-"," ")+"\n"+common+"\n"+text+"\n"
    return docs
